-- em falta (auditoria 2026-08-10; 138 → 167 completos).
-- Fármacos (faltam as 3): alprazolam, amicacina, amlodipina, amoxicilina,
-- benzilpenicilina-benzatina, cefazolina, cefepima, cefotaxima,
-- ceftazidima, clozapina, daptomicina, fenitoina, fenobarbital,
-- fenoximetilpenicilina, fluoxetina, fosfomicina, gentamicina,
-- haloperidol, lamotrigina, litio, moxifloxacina, nitroglicerina,
-- paracetamol, praziquantel, sertralina, tobramicina, tramadol,
-- valproato, vancomicina.
-- Padrão da 099/101/102: INSERT com JOIN (VALUES) ON d.slug = v.slug +
-- ON CONFLICT DO NOTHING, status 'published'.
-- Conteúdo autoral, ancorado nos rótulos aprovados DailyMed citados
-- (setIDs validados nas migrações 051–058/062–069/081/090/093–096).
-- Idempotente: reaplicar é seguro.
